mapper.sql:
WHERE s.clan_id = #{criteria.clanId}
AND ( LOWER(s.source_name) LIKE CONCAT('%', LOWER(#{criteria.keyword}), '%') OR LOWER(s.provider_name) LIKE CONCAT('%', LOWER(#{criteria.keyword}), '%') OR LOWER(s.book_title) LIKE CONCAT('%', LOWER(#{criteria.keyword}), '%') OR LOWER(s.volume_no) LIKE CONCAT('%', LOWER(#{criteria.keyword}), '%') OR LOWER(s.page_no) LIKE CONCAT('%', LOWER(#{criteria.keyword}), '%') OR LOWER(s.excerpt) LIKE CONCAT('%', LOWER(#{criteria.keyword}), '%') OR LOWER(s.description) LIKE CONCAT('%', LOWER(#{criteria.keyword}), '%') )
AND s.source_type = #{criteria.sourceType}
AND s.verification_status = #{criteria.verificationStatus}
AND s.privacy_level = #{criteria.privacyLevel}
AND EXISTS ( SELECT 1 FROM source_binding b WHERE b.source_id = s.id AND b.target_type = #{criteria.targetType} )
AND EXISTS ( SELECT 1 FROM source_attachment a WHERE a.source_id = s.id AND a.deleted_at IS NULL )
AND NOT EXISTS ( SELECT 1 FROM source_attachment a WHERE a.source_id = s.id AND a.deleted_at IS NULL )
AND EXISTS ( SELECT 1 FROM source_binding b WHERE b.source_id = s.id )
AND NOT EXISTS ( SELECT 1 FROM source_binding b WHERE b.source_id = s.id )

mapper.select:
SELECT s.*
FROM source s


LIMIT #{limit}
OFFSET #{offset}

SELECT *
FROM source
WHERE clan_id = #{clanId}
  AND id IN

    #{id}

ORDER BY id
